    template.print('<a href = "' + gs.getProperty('glide.servlet.uri') + '">' + "Test Link" + '</a>');

    template.print(url);

    template.print('<div style="font-size: 16px; font-weight: 600;">${comments_and_work_notes:1}</div>');



    var url1 = '<a href = "' + gs.getProperty('glide.servlet.uri') + '"  >' + 'Test Text' + '</a>';


	var test = '<a href = "'+ url+'">' + '</a>';

    template.print(url1);
})(current, template, email, email_action, event);
